import * as THREE from './three.module.js';
export function createCourtShoe(white,side=1){const shoe=new THREE.Group(),rubber=new THREE.MeshStandardMaterial({color:'#bdb9ad',roughness:1}),laceMat=new THREE.LineBasicMaterial({color:'#d7d4cb'});
 // Rounded heel, broad forefoot and tapered toe; the two soles mirror one another.
 const shape=new THREE.Shape();shape.moveTo(-.045,-.13);shape.bezierCurveTo(-.072,-.13,-.074,-.06,-.073,.03);shape.bezierCurveTo(-.085,.12,-.061,.174,-.006,.178);shape.bezierCurveTo(.062,.179,.083,.133,.077,.065);shape.bezierCurveTo(.068,-.01,.071,-.117,.045,-.13);shape.quadraticCurveTo(0,-.148,-.045,-.13);
 const soleGeo=new THREE.ExtrudeGeometry(shape,{depth:.017,bevelEnabled:true,bevelSegments:3,steps:1,bevelSize:.004,bevelThickness:.004,curveSegments:10});soleGeo.rotateX(Math.PI/2);soleGeo.translate(0,-.031,0);const sole=new THREE.Mesh(soleGeo,rubber);sole.scale.x=side;shoe.add(sole);
 const rings=[[-.132,.025,.012],[-.112,.054,.060],[-.065,.061,.088],[0,.070,.075],[.07,.077,.052],[.125,.060,.038],[.164,.031,.020],[.174,.004,.004]],positions=[],indices=[],steps=16;
 for(const [z,w,h] of rings)for(let j=0;j<=steps;j++){const a=j/steps*Math.PI;positions.push(side*(Math.cos(a)*w-.008*Math.max(0,z)/.18),-.026+Math.sin(a)*h,z);}
 for(let k=0;k<rings.length-1;k++)for(let j=0;j<steps;j++){const a=k*(steps+1)+j,b=a+steps+1;if(side>0)indices.push(a,a+1,b,a+1,b+1,b);else indices.push(a,b,a+1,a+1,b,b+1);}const upperGeo=new THREE.BufferGeometry();upperGeo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));upperGeo.setIndex(indices);upperGeo.computeVertexNormals();const cloth=white.clone();cloth.side=THREE.DoubleSide;const upper=new THREE.Mesh(upperGeo,cloth);shoe.add(upper);
 const heel=new THREE.Mesh(new THREE.SphereGeometry(1,14,10),cloth);heel.scale.set(.049,.033,.043);heel.position.set(0,.005,-.096);shoe.add(heel);
 const lacePoints=[];for(let z=-.045;z<=.045;z+=.026){const y=.058-Math.max(0,z)*.2;lacePoints.push(-.026,y,z,.026,y,z+.01);}const laceGeo=new THREE.BufferGeometry();laceGeo.setAttribute('position',new THREE.Float32BufferAttribute(lacePoints,3));shoe.add(new THREE.LineSegments(laceGeo,laceMat));shoe.traverse(o=>{if(o.isMesh)o.castShadow=true;});return shoe;}
